export class HitBottomObserver {
  private observer?: IntersectionObserver;
  private root?: HTMLDivElement;
  private target?: HTMLDivElement;
  private observingRoot?: HTMLDivElement;
  private observingTarget?: HTMLDivElement;

  constructor(private onHitBottom: () => void) {}

  setRoot(root?: HTMLDivElement) {
    if (this.root === root) {
      return;
    }
    this.root = root;
    this.sync();
  }

  setTarget(target?: HTMLDivElement) {
    if (this.target === target) {
      return;
    }
    this.target = target;
    this.sync();
  }

  disconnect() {
    this.observer?.disconnect();
    this.observer = undefined;
    this.observingRoot = undefined;
    this.observingTarget = undefined;
  }

  private sync() {
    if (this.observer && this.observingRoot === this.root && this.observingTarget === this.target) {
      return;
    }

    this.disconnect();

    if (!this.root || !this.target || typeof IntersectionObserver === 'undefined') {
      return;
    }

    this.observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          this.onHitBottom();
        }
      },
      {
        root: this.root,
        threshold: 0,
      },
    );
    this.observer.observe(this.target);
    this.observingRoot = this.root;
    this.observingTarget = this.target;
  }
}
