import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Prop,
  State,
  VNode,
  Watch,
} from '@stencil/core';
import { measureElement, type Virtualizer } from '@tanstack/virtual-core';
import { VirtualizerController } from './VirtualizerController';
import { HitBottomObserver } from './HitBottomObserver';
import { formatCSSLength } from '@src/shared/dom';
import { RenderConfig } from './types';

const DEFAULT_HEIGHT = 36;
const OVERSCAN = 4;
const GAP = 2;

/**
 * @part list
 */
@Component({
  tag: 'ks-virtual-list',
  shadow: true,
})
export abstract class KsVirtualList<T> implements ComponentInterface {
  @Element() el!: HTMLKsVirtualListElement;
  private virtualListScrollEl?: HTMLDivElement;
  private hitBottomSentinelEl?: HTMLDivElement;
  private readonly hitBottomObserver = new HitBottomObserver(() => this.emitHitBottom());

  protected abstract prefixCls: string;
  /** Specifies the items to be rendered. */
  @State() protected abstract items: Readonly<T[]>;
  /** Specifies the item renderer function. */
  protected abstract renderItem(item: T, index: number): VNode;
  /** Specifies the dynamic children renderer function for item. */
  protected abstract renderDynamicChildrenForItem(
    item: T,
    index: number,
    wrapWithSlot: (slotName: string, children: unknown) => unknown,
    renderConfig?: RenderConfig,
  ): unknown[];
  protected getPassThroughSlots?: (item: T, index: number) => VNode[];
  protected DEFAULT_HEIGHT: number | ((item: T) => number) = DEFAULT_HEIGHT;
  /** Specifies if the list should be virtualized. */
  @Prop() abstract virtual?: boolean | { estimatedItemHeight: number | ((item: T) => number) };

  /** Fired when the list scrolls to the bottom. */
  @Event({ bubbles: false, composed: false }) ksHitBottom!: EventEmitter<HTMLDivElement>;

  private emitHitBottom = () => {
    if (!this.virtualListScrollEl) {
      return;
    }
    this.ksHitBottom.emit(this.virtualListScrollEl);
  };

  private setVirtualListScrollEl = (el?: HTMLDivElement) => {
    if (this.virtualListScrollEl === el) {
      return;
    }
    this.virtualListScrollEl = el;
    this.hitBottomObserver.setRoot(el);
  };

  private setHitBottomSentinelEl = (el?: HTMLDivElement) => {
    if (this.hitBottomSentinelEl === el) {
      return;
    }
    this.hitBottomSentinelEl = el;
    this.hitBottomObserver.setTarget(el);
  };

  @State() hoveredIdx = -1;
  protected renderList() {
    if (this.virtual) {
      return this.renderVirtualList();
    } else {
      return (
        <div
          key="list-root"
          part="list"
          ref={this.setVirtualListScrollEl}
          class={`${this.prefixCls}__scroll-container`}
        >
          <ul
            style={{
              position: 'relative',
              height: 'fit-content',
              display: 'flex',
              flexDirection: 'column',
              gap: `${GAP}px`,
            }}
          >
            {this.items.map((item, index) => (
              <div
                key={index}
                style={{
                  display: 'contents',
                }}
                // eslint-disable-next-line react/jsx-no-bind
                onMouseEnter={() => (this.hoveredIdx = index)}
                // eslint-disable-next-line react/jsx-no-bind
                onMouseLeave={() => (this.hoveredIdx = -1)}
              >
                {this.renderItem(item, index)}
              </div>
            ))}
            <div
              aria-hidden="true"
              ref={this.setHitBottomSentinelEl}
              style={{
                position: 'absolute',
                left: '0px',
                bottom: '0px',
                width: '100%',
                height: '1px',
                pointerEvents: 'none',
              }}
            />
          </ul>
        </div>
      );
    }
  }

  private renderVirtualList() {
    const virtualizer = this.virtualizerController?.getVirtualizer();
    if (!virtualizer) {
      return null;
    }
    const virtualItems = virtualizer.getVirtualItems();

    const totalSize = virtualizer.getTotalSize();
    return (
      <div key="list-root" part="list" ref={this.setVirtualListScrollEl} class={`${this.prefixCls}__scroll-container`}>
        <ul
          style={{
            position: 'relative',
            width: 'auto',
            height: formatCSSLength(totalSize),
          }}
        >
          {virtualItems.map(({ key, index, start }) => (
            <div
              key={key.toString()}
              data-index={index}
              ref={(el) => el && virtualizer.measureElement(el)}
              style={{
                position: 'absolute',
                top: '0px',
                left: '0px',
                width: '100%',
                height: 'auto',
                transform: `translateY(${start}px)`,
              }}
              // eslint-disable-next-line react/jsx-no-bind
              onMouseEnter={() => (this.hoveredIdx = index)}
              // eslint-disable-next-line react/jsx-no-bind
              onMouseLeave={() => (this.hoveredIdx = -1)}
            >
              {this.renderItem(this.items[index] as T, index)}
            </div>
          ))}
          <div
            aria-hidden="true"
            ref={this.setHitBottomSentinelEl}
            style={{
              position: 'absolute',
              top: formatCSSLength(totalSize),
              left: '0px',
              width: '100%',
              height: '1px',
            }}
          />
        </ul>
      </div>
    );
  }

  private virtualizerController?: VirtualizerController<HTMLDivElement, HTMLElement>;
  private virtualIndexes: number[] = [];
  private initVirtualizerController = () => {
    this.virtualizerController = new VirtualizerController(this, {
      getScrollElement: () => this.virtualListScrollEl!,
      count: this.items.length,
      gap: GAP,
      estimateSize: (index) => {
        const item = this.items[index] as T;
        let estimatedHeight: number;

        if (typeof this.virtual === 'object' && this.virtual.estimatedItemHeight) {
          estimatedHeight =
            typeof this.virtual.estimatedItemHeight === 'function'
              ? this.virtual.estimatedItemHeight(item)
              : this.virtual.estimatedItemHeight;
        } else {
          estimatedHeight = typeof this.DEFAULT_HEIGHT === 'function' ? this.DEFAULT_HEIGHT(item) : this.DEFAULT_HEIGHT;
        }

        return estimatedHeight;
      },
      measureElement: (el, entry, virtualizer) => measureElement(el, entry, virtualizer),
      onChange: (instance: Virtualizer<HTMLDivElement, HTMLElement>) => {
        const virtualIndexes = instance.getVirtualIndexes();
        if (!Object.is(virtualIndexes, this.virtualIndexes)) {
          this.virtualIndexes = virtualIndexes;
          this.__pendingUpdateDeps = true;
        }
      },
      overscan: OVERSCAN,
    });
  };

  private __pendingUpdateDeps = false;
  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('items')
  watchItems() {
    if (this.virtual) {
      const virtualizer = this.virtualizerController?.getVirtualizer();
      virtualizer?.setOptions({ ...virtualizer.options, count: this.items.length });
      virtualizer?.measure();
    }
    this.__pendingUpdateDeps = true;
  }

  @Watch('hoveredIdx')
  watchHoveredIdx() {
    this.__pendingUpdateDeps = true;
  }

  componentWillLoad(): Promise<void> | void {
    // 这里在 willLoad 里才初始化的原因：stencil 无法在 constructor 里拿到 items
    this.initVirtualizerController();
  }

  componentDidRender() {
    if (this.__pendingUpdateDeps) {
      this.__pendingUpdateDeps = false;
      if (this.virtual) {
        this.setDynamicRenderDeps(
          this.virtualIndexes.flatMap<unknown>((index) =>
            this.renderDynamicChildrenForItem(this.items[index] as T, index, this.wrapWithSlot, {
              hovering: index === this.hoveredIdx,
            }),
          ),
          () =>
            this.virtualIndexes.flatMap<VNode>(
              (index) => this.getPassThroughSlots?.(this.items[index] as T, index) || [],
            ),
        );
      } else {
        this.setDynamicRenderDeps(
          this.items.flatMap<unknown>((item, index) =>
            this.renderDynamicChildrenForItem(item, index, this.wrapWithSlot, {
              hovering: this.hoveredIdx === this.items.indexOf(item),
            }),
          ),
          () => this.items.flatMap<VNode>((item, index) => this.getPassThroughSlots?.(item, index) || []),
        );
      }
    }
  }

  disconnectedCallback() {
    this.hitBottomObserver.disconnect();
  }

  connectedCallback?(): void;
  componentWillRender?(): Promise<void> | void;

  /** set dynamic children from hydration level */
  protected setDynamicRenderDeps!: (children: unknown[], getPassThroughSlots?: () => VNode[]) => void;
  protected wrapWithSlot!: (slotName: string, children: unknown) => unknown;
}
