import { ComponentInterface, forceUpdate } from '@stencil/core';
import {
  elementScroll,
  observeElementOffset,
  observeElementRect,
  PartialKeys,
  Virtualizer,
  VirtualizerOptions,
} from '@tanstack/virtual-core';

type HostComponent = ComponentInterface & { el: HTMLElement } & { isConnected?: boolean };

const hijackStencilLifeCycle = (
  host: HostComponent,
  hijack: Record<keyof ComponentInterface, ComponentInterface[keyof ComponentInterface]>,
) => {
  Object.keys(hijack).forEach((key) => {
    const originalLifeCycle = host[key];
    host[key] = () => {
      originalLifeCycle?.call(host);
      hijack[key]?.();
    };
  });
};

class VirtualizerControllerBase<TScrollElement extends Element | Window, TItemElement extends Element> {
  host: HostComponent;

  private readonly virtualizer: Virtualizer<TScrollElement, TItemElement>;

  private cleanup?: () => void;

  constructor(host: HostComponent, options: VirtualizerOptions<TScrollElement, TItemElement>) {
    this.host = host;

    const resolvedOptions = {
      ...options,
      onChange: (instance: Virtualizer<TScrollElement, TItemElement>, sync: boolean) => {
        forceUpdate(host.el);
        options.onChange?.(instance, sync);
      },
    };
    this.virtualizer = new Virtualizer(resolvedOptions);

    if (host.isConnected) {
      // 因为 stencil 的原因，contructor 可能不会在 connectedCallback 之前被调用
      // 因此如果此时已经 connected 了，需要手动调用 _didMount
      this.cleanup = this.virtualizer._didMount();
    }

    /**
     * 劫持 stencil 声明周期
     * - 在组件挂载时调用 virtualizer._didMount
     * - 在组件卸载时调用 virtualizer._willUnmount
     * - 在组件渲染时调用 virtualizer._willUpdate
     */
    hijackStencilLifeCycle(host, {
      connectedCallback: () => {
        this.cleanup = this.virtualizer._didMount();
      },
      disconnectedCallback: () => {
        this.cleanup?.();
      },
      componentDidRender: () => {
        this.virtualizer._willUpdate();
      },
    });
  }

  public getVirtualizer() {
    return this.virtualizer;
  }
}

export class VirtualizerController<
  TScrollElement extends Element,
  TItemElement extends Element,
> extends VirtualizerControllerBase<TScrollElement, TItemElement> {
  constructor(
    host: HostComponent,
    options: PartialKeys<
      VirtualizerOptions<TScrollElement, TItemElement>,
      'observeElementRect' | 'observeElementOffset' | 'scrollToFn'
    >,
  ) {
    super(host, {
      observeElementRect,
      observeElementOffset,
      scrollToFn: elementScroll,
      ...options,
    });
  }
}
